function sheet65(c){const s=c.stats;return '<div class="identity13 sheet65"><img src="'+esc(window.eldoria52Art.hero[c.cls][0])+'" alt=""><div><small>'+esc(voc[c.cls])+'</small><h3>'+esc(c.name)+'</h3><small>'+esc(c.activeTitle?.name||'Sem título')+'</small><p>Nível '+c.level+' · '+nf(c.xp)+' / '+nf(c.xpNeed)+' XP</p>'+masteryProgress(c)+'</div><b>'+nf(c.power)+' Poder</b></div><div class="stats65">'+[['Vida',s.hp],['Mana',s.mana],['Dano',s.damage],['Defesa',s.def],['Crítico',Math.round(s.crit*10000)/100+'%'],['Dano crítico',nf(Math.round(s.critMult*100)/100)+'×'],['Ataque extra',nf(Math.round(s.haste*10000)/100)+'%'],['Tenacidade',nf(Math.round(s.tenacity*10000)/100)+'%'],['Bônus de cura',nf(Math.round(s.heal*10000)/100)+'%'],['Maestria',c.skill]].map(([k,v])=>'<div class="stat13"><small>'+k+'</small><b>'+esc(typeof v==='number'?nf(Math.round(v*100)/100):v)+'</b></div>').join('')+'</div>';}

